#################################################################
# Disjointness
#################################################################
:Organization owl:disjointWith :Item, :Address, :AgentRole, :Price .
:Item owl:disjointWith :Address, :AgentRole .
:Price owl:disjointWith :Organization, :Item, :AgentRole .
:AgentRole owl:disjointWith :Address, :Item, :Price .
:HeaderSection owl:disjointWith :DetailSection, :SummarySection .
:DetailSection owl:disjointWith :SummarySection .

#################################################################
# Advanced Axioms & Restrictions (Mandatory fields)
#################################################################
:InvoiceParticipantRoleAssignment rdfs:subClassOf
    [ a owl:Restriction ; owl:onProperty :inInvoice ; owl:cardinality "1"^^xsd:nonNegativeInteger ],
    [ a owl:Restriction ; owl:onProperty :hasRole ; owl:cardinality "1"^^xsd:nonNegativeInteger ],
    [ a owl:Restriction ; owl:onProperty :hasAddress ; owl:cardinality "1"^^xsd:nonNegativeInteger ] .

:LineItem rdfs:subClassOf
    [ a owl:Restriction ; owl:onProperty :describesItem ; owl:cardinality "1"^^xsd:nonNegativeInteger ],
    [ a owl:Restriction ; owl:onProperty :hasPrice ; owl:cardinality "1"^^xsd:nonNegativeInteger ],
    [ a owl:Restriction ; owl:onProperty :quantity ; owl:minCardinality "1"^^xsd:nonNegativeInteger ] .

:InvoiceMessage rdfs:subClassOf
    [ a owl:Restriction ; owl:onProperty :hasSegment ; owl:someValuesFrom :HeaderSection ],
    [ a owl:Restriction ; owl:onProperty :hasSegment ; owl:someValuesFrom :DetailSection ],
    [ a owl:Restriction ; owl:onProperty :hasSegment ; owl:someValuesFrom :SummarySection ],
    [ a owl:Restriction ; owl:onProperty :invoiceNumber ; owl:minCardinality "1"^^xsd:nonNegativeInteger ] .

:Organization rdfs:subClassOf
    [ a owl:Restriction ; owl:onProperty :organizationName ; owl:minCardinality "1"^^xsd:nonNegativeInteger ],
    [ a owl:Restriction ; owl:onProperty :hasIdentifier ; owl:minCardinality "1"^^xsd:nonNegativeInteger ] .

:Address rdfs:subClassOf
    [ a owl:Restriction ; owl:onProperty :streetName ; owl:minCardinality "1"^^xsd:nonNegativeInteger ],
    [ a owl:Restriction ; owl:onProperty :city ; owl:minCardinality "1"^^xsd:nonNegativeInteger ],
    [ a owl:Restriction ; owl:onProperty :postalCode ; owl:minCardinality "1"^^xsd:nonNegativeInteger ],
    [ a owl:Restriction ; owl:onProperty :countryCode ; owl:minCardinality "1"^^xsd:nonNegativeInteger ] .

